mapper.select:
SELECT FROM portal_app
ORDER BY create_time DESC, id DESC
LIMIT #{offset}, #{pageSize}

mapper.update:
UPDATE portal_app
name = #{dto.name}, code = #{dto.code}, context_path = #{dto.contextPath}, index_path = #{dto.indexPath}, domain = #{dto.domain}, ip = #{dto.ip}, port = #{dto.port}, business_bp = #{dto.businessBp}, description = #{dto.description}, icon = #{dto.icon}, business_scene = #{dto.businessScene}, capability_tag = #{dto.capabilityTag}, source = #{dto.source}, updated_by = #{updatedBy}, update_time = CURRENT_TIMESTAMP
WHERE id = #{appId}
